(() => {
'use strict';
const D=window.PHONE_DATA,G=window.PHOTO_LIBRARY,C=window.PhoneCore,$=s=>document.querySelector(s),phone=$('#phone'),screen=$('#screen'),modalRoot=$('#modal-root');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=C.normalize(JSON.parse(localStorage.getItem(C.key)));}catch{state=C.defaults();}
let route=state.unlocked?{app:'home'}:{app:'lock'},pendingApp=null,pin='',pinError=false,modalStack=[],lastFocus=null,toastTimer,swRunning=false,swElapsed=0,swStart=0,clockTab='alarms',dial='',calendarOffset=0,calendarSelected=new Date().getDate();
const apps=[['messages','信息'],['calendar','日历'],['photos','照片'],['camera','相机'],['clock','时钟'],['maps','地图'],['notes','备忘录'],['reminders','提醒事项'],['store','App Store'],['settings','设置'],['calculator','计算器'],['wechat','微信']];
const dock=[['phone','电话'],['safari','Safari'],['messages','信息'],['camera','相机']];
const allApps=[...apps,...dock.filter(([id])=>!apps.some(a=>a[0]===id))];
const findPerson=id=>D.people.find(p=>p.id===id);
const findScene=id=>{for(const p of D.people){const s=p.scenes.find(x=>x.id===id);if(s)return {p,s};}return null;};
const personStyle=p=>`--accent:${esc(p.color)}`;
const avatar=(p,large=false)=>`<span class="avatar${large?' large':''}" style="${personStyle(p)}">${esc(p.initial)}</span>`;
const btn=(action,label,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const X=window.PhoneExperience.create({data:D,gallery:G,esc,icon,btn,shell,go,save,toast,modal:showModal,appIcon,getState:()=>state,getRoute:()=>route,render,closeModal});
const Y=window.DaliExperience.create({gallery:G,esc,icon,btn,shell,go,save,toast,getState:()=>state,getRoute:()=>route});
function save(){try{localStorage.setItem(C.key,JSON.stringify(state));}catch{toast('浏览器未允许保存；本次探索仍可继续。');}}
function toast(text){clearTimeout(toastTimer);const el=$('#toast');el.textContent=text;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),2600);}
function time(){return new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());}
function date(){return new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());}
function applySettings(){phone.classList.toggle('dark',state.settings.dark);phone.classList.toggle('reduced',state.settings.reduced);$('.wallpaper').style.filter=`brightness(${Math.max(45,Math.min(100,state.settings.brightness))/100})`;}
function status(){phone.classList.toggle('is-locked',['lock','pin'].includes(route.app));const dark=!['lock','pin','home','camera','weather'].includes(route.app);$('#statusbar').classList.toggle('status-dark',dark);$('#statusbar').innerHTML=`<span data-clock>${time()}</span><span class="status-icons"><span class="signal"><i></i><i></i><i></i><i></i></span>${icon('wifi')}<span class="battery">78</span></span>`;phone.classList.toggle('in-app',dark);}
function go(app,opts={},replace=false){X.onNavigate();closeModal(true);route={app,...opts};if(!['lock','pin'].includes(app)&&!state.opened.includes(app)){state.opened.push(app);save();}history[replace?'replaceState':'pushState']({phone:true,route},'');render();}
function back(){if(modalStack.length){closeModal();return;}if(route.app==='room'||route.app==='moments')go('wechat',{},true);else if(route.app==='album'){if(route.returnRoom)go('room',{id:route.returnRoom},true);else go('photos',{},true);}else if(route.app==='memo'||route.app==='files')go('notes',{},true);else if(route.app==='pin')go('lock',{},true);else if(route.app!=='home'&&route.app!=='lock')go('home',{},true);else if(route.app==='home'){state.unlocked=false;save();go('lock',{},true);}}
history.replaceState({phone:true,route},'');
window.addEventListener('popstate',ev=>{if(modalStack.length){history.pushState({phone:true,route},'');closeModal();return;}if(ev.state?.phone){X.onNavigate();route=ev.state.route;render();}else{route={app:state.unlocked?'home':'lock'};history.replaceState({phone:true,route},'');render();}});
function shell(title,body,{right='',footer='',className='',scrollClass=''}={}){return `<section class="app-shell ${className}"><nav class="app-nav">${btn('back',icon('back')+'<span>返回</span>','nav-back')}<h1>${esc(title)}</h1><div class="nav-action">${right}</div></nav><div class="app-scroll ${scrollClass}">${body}</div>${footer}</section>`;}
function appButton(id,label,isDock=false){const unread=id==='wechat'?X.unreadCount():0;return `<button class="app-button" data-action="app" data-app="${id}" aria-label="${esc(label)}">${appIcon(id)}${!isDock?`<span class="app-label">${esc(label)}</span>`:''}${unread&&!isDock?'<span class="badge">'+unread+'</span>':''}</button>`;}
function lock(){return `<section class="lockscreen realistic-lock"><div class="lock-symbol">${icon('lock')}</div><p class="lock-date">${date()}</p><h1 class="lock-time" data-clock>${time()}</h1><div class="lock-notifications"><button class="notification password-notification" data-action="pin"><span class="lock-notification-icon">${appIcon('notes')}</span><span class="lock-notification-copy"><span class="notification-top">备忘录 <time>现在</time></span><h3>锁屏提示</h3><p>别再忘了，密码还是 <strong>0520</strong> ❤️</p></span></button><button class="notification" data-action="lock-notification"><span class="lock-notification-icon">${appIcon('wechat')}</span><span class="lock-notification-copy"><span class="notification-top">微信 <time>现在</time></span><h3>小王</h3><p>本来也没让你松呀🤍</p></span></button></div><div class="lock-bottom"><div class="lock-tools">${btn('flashlight',icon('flash'),'circle-button','aria-label="手电筒"')}${btn('lock-camera',icon('camera'),'circle-button','aria-label="打开相机"')}</div>${btn('pin','向上轻扫以打开','unlock-button')}${btn('unlock','直接进入','lock-direct-entry','aria-label="直接进入桌面"')}</div></section>`;}
function passcode(){const letters={2:'ABC',3:'DEF',4:'GHI',5:'JKL',6:'MNO',7:'PQRS',8:'TUV',9:'WXYZ'};return `<section class="passcode realistic-passcode ${pinError?'pin-error':''}"><h2>输入密码</h2><div class="pin-dots">${[0,1,2,3].map(i=>`<i class="pin-dot ${pin.length>i?'filled':''}"></i>`).join('')}</div><p class="pin-error-message" role="status">${pinError?'密码不对，再试一次。':''}</p><div class="pin-grid">${[1,2,3,4,5,6,7,8,9,'',0,'⌫'].map(n=>n===''?'<span></span>':btn('pin-key',`<span class="pin-number">${n}</span>${letters[n]?`<small>${letters[n]}</small>`:''}`,'pin-key'+(n==='⌫'?' small':''),`data-key="${n}" aria-label="${n==='⌫'?'删除':n}"`)).join('')}</div><div class="pin-footer">${btn('unlock','直接进入')}${btn('back','取消')}</div></section>`;}

function unlock(){clearTimeout(toastTimer);$('#toast').classList.remove('visible');phone.classList.add('unlocking');setTimeout(()=>phone.classList.remove('unlocking'),280);state.unlocked=true;state.seenIntro=true;save();const target=pendingApp;pendingApp=null;pin='';if(target==='wang')go('room',{id:D.people[0].id,scene:0});else go(target||'home');}
function home(){const d=new Date();return `<section class="home"><div class="widgets"><button class="widget weather-widget" data-action="app" data-app="weather" aria-label="天气"><div class="weather-temp">28°</div>${icon('cloud')}<p>多云</p><small>最高 32° 最低 24°</small></button><button class="widget calendar-widget" data-action="app" data-app="calendar" aria-label="日历"><div class="widget-date"><strong>${d.getDate()}</strong><span>${new Intl.DateTimeFormat('zh-CN',{weekday:'short'}).format(d)}<br><em>${d.getMonth()+1}月</em></span></div><div class="event">散步<small>19:00 — 20:00</small></div><div class="event blue">整理照片<small>21:00 — 22:00</small></div></button></div><div class="app-grid">${apps.map(([id,label])=>appButton(id,label)).join('')}</div><div class="home-space"></div><div class="page-controls">${btn('search',icon('search')+'搜索','search-pill')}<span class="page-dot active"></span>${btn('second-page','','page-dot','aria-label="扩展页面"')}</div><div class="dock">${dock.map(([id,label])=>appButton(id,label,true)).join('')}</div></section>`;}
function contactRows(list=D.people){return X.wechat();}
function wechat(){return X.wechat();}
function room(){return X.room();}
function markViewed(s){if(!state.viewed.includes(s.id)){state.viewed.push(s.id);save();}}
function memorySheet(id){const f=findScene(id);if(!f)return;const {p,s}=f;markViewed(s);const verified=C.canQuote(s),candidate=false,showQuote=verified||candidate,saved=state.favorites.includes(s.id);return `<p class="eyebrow">${esc(p.name)} · ${esc(s.title)}</p><h2>${s.status==='editorial'?'未完待续':showQuote?'留在片段里的话':'留住这个瞬间'}</h2><span class="pill ${verified?'green':''}">${verified?'公开视频摘录':candidate?'审校预览 · 候选文稿':s.status==='editorial'?'未完待续':'公开片段待核实'}</span><p class="quote">${esc(showQuote?s.quote:s.narrative)}</p><p class="quote-label">${showQuote?(verified?'说话者：'+esc(s.speaker):'说话者、原声、时间戳尚待核实'):''}</p>${!showQuote&&s.status!=='editorial'?'':''}<div class="sheet-actions">${btn('favorite',icon(saved?'check':'star')+(saved?'已收藏':'收藏此刻'),'primary-button '+(saved?'saved':''),`data-id="${s.id}"`)}</div>`;}
function showModal(kind,data={},replace=false){X.stopAudio();if(!modalStack.length)lastFocus=document.activeElement;if(replace)modalStack.pop();modalStack.push({kind,data});renderModal();}
function closeModal(all=false){if(all)modalStack=[];else modalStack.pop();if(modalStack.length)renderModal();else{modalRoot.innerHTML='';screen.removeAttribute('inert');if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});}}
function renderModal(){const m=modalStack.at(-1);if(!m){closeModal(true);return;}let html='';if(m.kind==='photo'){renderPhotoViewer(m);return;}if(m.kind==='memory')html=memorySheet(m.data.id);else if(m.kind==='phone-actions')html=X.renderActions(m.data);else if(m.kind==='intro')html=`<p class="eyebrow">小圣的手机</p><h2>给记得这些故事的你。</h2><p>这是一部可以探索的手机，也是一本关于公开影像的章节集。打开微信，从一个熟悉的名字开始。</p><div class="list-group"><div class="list-row">${icon('bubble')}<span class="row-label">打开片段<small>点开联系人，逐段浏览。</small></span></div><div class="list-row">${icon('star')}<span class="row-label">收藏此刻<small>收藏会保存在这台设备的浏览器里。</small></span></div><div class="list-row">${icon('folder')}<span class="row-label">发现隐藏档案<small>收藏三个不同人物的章节后，去备忘录看看。</small></span></div></div>${btn('modal-close','知道了，开始探索','primary-button wide')}`;
else if(m.kind==='search')html=`<h2>搜索</h2><label class="search-field" style="margin:15px 0">${icon('search')}<input id="global-search" type="search" placeholder="应用、联系人、.memories" aria-label="搜索应用或联系人" autofocus></label><div id="search-results" class="search-results">${searchResults('')}</div>`;
else if(m.kind==='person') {const p=findPerson(route.id);html=`<h2>${esc(p.name)}</h2><p>${esc(p.subtitle)}</p>${btn('modal-close','返回章节','primary-button wide')}`;}
else if(m.kind==='reset')html=`<h2>重新开始这次探索？</h2><p>将清除本浏览器里保存的阅读、收藏、备忘录与设置。</p><div class="sheet-actions">${btn('modal-close','保留进度','secondary-button')}${btn('reset-confirm','清除并重新开始','primary-button')}</div>`;
else if(m.kind==='alarm')html=`<h2>添加闹钟</h2><form data-form="alarm"><label class="form-label" for="alarm-time">时间</label><input class="text-input" id="alarm-time" type="time" value="08:00" required><label class="form-label" for="alarm-label">标签</label><input id="alarm-label" class="text-input" placeholder="闹钟" maxlength="40"><button class="primary-button wide" type="submit">保存闹钟</button></form>`;
else if(m.kind==='note')html=`<h2>写一条备忘录</h2><form data-form="note"><label class="form-label" for="note-title">标题</label><input id="note-title" class="text-input" maxlength="60" required placeholder="今天想记住的"><label class="form-label" for="note-text">内容</label><textarea id="note-text" class="text-area" maxlength="4000" placeholder="只保存在当前浏览器…" required></textarea><button type="submit" class="primary-button wide" style="margin-top:16px">保存</button></form>`;
else if(m.kind==='reminder')html=`<h2>添加提醒事项</h2><form data-form="reminder"><input id="reminder-text" aria-label="提醒内容" class="text-input" maxlength="120" required placeholder="想做的一件事"><button type="submit" class="primary-button wide" style="margin-top:15px">添加</button></form>`;
else if(m.kind==='call')html=`<h2>电话</h2><p style="font-size:25px;color:var(--fg)">${esc(dial||'小圣的手机')}</p><p>暂无法接通</p>${btn('modal-close',icon('phone')+'结束通话','primary-button wide','style="background:#c95f55"')}`;
else if(m.kind==='review')html=`<h2>内容整理中</h2>${btn('modal-close','返回','primary-button wide')}`;
else if(m.kind==='capture')html=Y.capture();
else if(m.kind==='about-data')html=`<h2>这部手机如何保存记忆</h2><p>粉丝同人创作，角色对话为虚构演绎，非真实私人聊天。三位角色的情景回复在本机运行，聊天详情可暂停、清除记忆或动态记录。</p><p>收藏、已读状态、设置、备忘录和信息保存在当前浏览器，不会跨设备同步。清理浏览器数据会清除进度。</p>${btn('modal-close','明白了','primary-button wide')}`;
else if(m.kind==='second')html=`<h2>留一点空白。</h2><p>桌面扩展页留给之后的内容。新人物会直接加入微信联系人，无需增加桌面图标。</p>${btn('modal-close','回到桌面','primary-button wide')}`;
modalRoot.innerHTML=`<div class="modal-shade" data-action="shade-close"><section class="sheet" role="dialog" aria-modal="true" aria-label="详情" tabindex="-1"><div class="sheet-grab"></div>${btn('modal-close',icon('close'),'sheet-close','aria-label="关闭详情"')}${html}</section></div>`;screen.setAttribute('inert','');const focus=$('.sheet [autofocus]')||$('.sheet-close');focus?.focus({preventScroll:true});}
function searchResults(q){q=q.trim().toLowerCase();const appMatches=allApps.filter(([id,name])=>name.toLowerCase().includes(q)||id.includes(q));const personMatches=D.people.filter(p=>(p.name+' '+(p.alias||'')).toLowerCase().includes(q));const folder=q&&'.memories'.includes(q);return appMatches.map(([id,name])=>`<button class="contact-row" data-action="search-app" data-app="${id}">${appIcon(id)}<span>${name}</span></button>`).join('')+personMatches.map(p=>`<button class="contact-row" data-action="search-person" data-id="${p.id}">${avatar(p)}<span>${esc(p.name)}</span></button>`).join('')+(folder?btn('files',icon('folder')+' .memories','list-row'):'')+(!appMatches.length&&!personMatches.length&&!folder?'<p class="no-results">没有找到，换个名字试试。</p>':'');}
function enterPin(key){
 if(key==='⌫'){pin=pin.slice(0,-1);pinError=false;}else if(/^\d$/.test(key)&&pin.length<4){pin+=key;pinError=false;}
 if(pin.length===4){if(pin===G.unlock.pin){unlock();return;}pin='';pinError=true;toast('密码不对，请重新输入四位密码。');}
 render();
}
function albumItems(id){const album=G.albums.find(a=>a.id===id);return album?album.items.map(id=>G.assets.find(a=>a.id===id)).filter(Boolean):[];}
function photoPath(asset){return asset.path;}
function albumCards(){return `<div class="album-cards">${G.albums.map(a=>{const cover=G.assets.find(x=>x.id===a.coverAssetId)||albumItems(a.id)[0];return `<button class="album-card" data-action="album" data-id="${esc(a.id)}" aria-label="打开相册 ${esc(a.name)}"><span class="album-cover"><img src="${esc(photoPath(cover))}" alt="${esc(a.name)}相册封面" loading="lazy" decoding="async"></span><strong>${esc(a.name)}</strong><span>${albumItems(a.id).length} 张</span></button>`;}).join('')}</div>`;}
function albumPage(){const album=G.albums.find(a=>a.id===route.id);if(!album)return photos(false);const items=albumItems(album.id);return shell(album.name,`<div class="album-heading"><h2>${esc(album.name)}</h2><p>${items.length} 张照片</p></div><div class="album-photo-grid">${items.map((a,i)=>`<button class="album-thumbnail" data-action="photo" data-index="${i}" aria-label="查看照片 ${i+1}：${esc(a.description)}"><img src="${esc(photoPath(a))}" alt="${esc(a.description)}" loading="lazy" decoding="async"></button>`).join('')}</div>`);}
function renderPhotoViewer(m){const items=m.data.assetId?G.assets.filter(a=>a.id===m.data.assetId):albumItems(m.data.albumId),album=G.albums.find(a=>a.id===m.data.albumId),title=m.data.assetId?'照片':album.name;m.data.index=Math.max(0,Math.min(m.data.index,items.length-1));const asset=items[m.data.index];if(!asset){closeModal();return;}modalRoot.innerHTML=`<section class="photo-viewer" role="dialog" aria-modal="true" aria-label="${esc(title)}查看器"><div class="viewer-status" data-clock>${time()}</div><header class="viewer-nav">${btn('modal-close',icon('back')+'关闭','','aria-label="关闭照片"')}<p aria-live="polite">${esc(title)} ${m.data.assetId?'':`<span>${m.data.index+1} / ${items.length}</span>`}</p><span class="viewer-nav-spacer"></span></header><div class="viewer-image-area"><img class="viewer-image" src="${esc(photoPath(asset))}" alt="${esc(asset.description)}" draggable="false"><p class="viewer-error" hidden>这张照片暂时无法加载，请切换后重试。</p></div><footer class="viewer-footer"><p>${esc(asset.description)}</p>${m.data.assetId?'':`<div class="viewer-controls">${btn('photo-step',icon('back'),'viewer-step',`data-delta="-1" aria-label="上一张照片" ${m.data.index===0?'disabled':''}`)}<span>左右滑动查看</span>${btn('photo-step',icon('chevron'),'viewer-step',`data-delta="1" aria-label="下一张照片" ${m.data.index===items.length-1?'disabled':''}`)}</div>`}</footer></section>`;screen.setAttribute('inert','');$('.photo-viewer button').focus({preventScroll:true});}
function movePhoto(delta){const m=modalStack.at(-1);if(m?.kind!=='photo'||m.data.assetId)return;const next=m.data.index+delta;if(next>=0&&next<albumItems(m.data.albumId).length){m.data.index=next;renderPhotoViewer(m);}}

function photos(favoritesOnly=false){
 if(!favoritesOnly)return shell('照片',`<div class="padded"><h2 class="large-title">相簿</h2>${albumCards()}${state.captures?Y.captureCard():''}</div>`);
 const entries=D.people.flatMap(p=>p.scenes.filter(s=>state.favorites.includes(s.id)).map(s=>({p,s})));
 return shell('收藏',`<div class="padded"><h2 class="large-title">我的收藏</h2>${entries.length?`<div class="gallery-grid">${entries.map(({p,s})=>`<button class="photo-card" data-action="memory" data-id="${s.id}" style="${personStyle(p)}"><div class="photo-image ${p.id===D.people[0].id?'':'abstract'}"><span class="photo-initial">${esc(p.initial)}</span><b>${esc(p.name)}</b><small>${esc(s.title)}</small></div><p>♥ 已收藏</p></button>`).join('')}</div>`:`<div class="empty-state">${icon('star')}<h3>还没有收藏</h3><p>喜欢的片段可以收藏在这里。</p>${btn('app','打开微信','secondary-button','data-app="wechat"')}</div>`}</div>`);
}
function settings(){return shell('设置',`<div class="padded"><h2 class="large-title">设置</h2><div class="settings-profile" data-action="wx-egg" role="button" tabindex="0"><span class="avatar large" style="--accent:#6d8a84">圣</span><div><h3>小圣的手机</h3><p>小圣</p></div></div><div class="section-label">显示与体验</div><div class="list-group">${settingRow('dark','深色模式','让应用界面更适合夜间阅读')}${settingRow('reduced','减少动态效果','简化打开应用与卡片动画')}<div class="range-row">${icon('sun')}<input id="brightness" aria-label="壁纸亮度" type="range" min="45" max="100" value="${state.settings.brightness}">${icon('sun')}</div></div><div class="section-label">内容</div><div class="list-group">${btn('intro','<span class="row-label">关于这部手机</span>'+icon('chevron'),'list-row')}${btn('data-info','<span class="row-label">数据与保存</span>'+icon('chevron'),'list-row')}<button type="button" class="list-row" data-dev-support data-support-from="settings" aria-label="支持开发者"><span class="row-label">支持开发者<small>微信 ¥0.99 · 自愿支持</small></span>${icon('chevron')}</button></div><div class="list-group">${btn('lock-phone',icon('lock')+'<span class="row-label">锁定手机</span>','list-row')}${btn('reset','重新开始探索','list-row danger')}</div></div>`);}
function settingRow(key,title,desc){return `<div class="list-row"><span class="row-label">${title}<small>${desc}</small></span><button class="toggle ${state.settings[key]?'on':''}" data-action="setting" data-key="${key}" role="switch" aria-checked="${!!state.settings[key]}" aria-label="${title}"></button></div>`;}
function calendar(){const now=new Date(),shown=new Date(now.getFullYear(),now.getMonth()+calendarOffset,1),year=shown.getFullYear(),month=shown.getMonth(),count=new Date(year,month+1,0).getDate(),start=(shown.getDay()+6)%7;calendarSelected=Math.min(calendarSelected,count);return shell('日历',`<div class="padded"><div class="calendar-toolbar">${btn('month',icon('back'),'','data-delta="-1" aria-label="上个月"')}<h2>${year}年 ${month+1}月</h2>${btn('month',icon('chevron'),'','data-delta="1" aria-label="下个月"')}</div><div class="calendar-week">${['一','二','三','四','五','六','日'].map(x=>'<span>'+x+'</span>').join('')}</div><div class="calendar-grid">${'<span></span>'.repeat(start)}${Array.from({length:count},(_,i)=>btn('date',i+1,(calendarSelected===i+1?'selected':(i+1===now.getDate()&&calendarOffset===0?'today':'')),`data-date="${i+1}"`)).join('')}</div><div class="agenda"><h3>${month+1}月${calendarSelected}日</h3><div class="list-group" style="margin-top:18px"><div class="list-row"><span style="color:#da6871">19:00</span><span class="row-label">散步<small>留一点时间给晚霞</small></span></div><div class="list-row"><span style="color:#688cd1">21:00</span><span class="row-label">整理照片<small>挑出今天最喜欢的一张</small></span></div></div></div></div>`,{right:btn('today','今天')});}
function clock(){return shell('时钟',`<div class="padded"><div class="clock-tabs">${btn('clock-tab','闹钟',clockTab==='alarms'?'active':'','data-tab="alarms"')}${btn('clock-tab','秒表',clockTab==='stopwatch'?'active':'','data-tab="stopwatch"')}</div>${clockTab==='alarms'?`<h2 class="large-title">闹钟</h2>${state.alarms.map((a,i)=>`<div class="alarm-row"><div class="alarm-copy"><div class="alarm-time">${esc(a.time)}</div><p>${esc(a.label)}</p></div><button class="toggle ${a.on?'on':''}" role="switch" aria-checked="${a.on}" aria-label="${esc(a.time)}闹钟" data-action="alarm-toggle" data-index="${i}"></button></div>`).join('')}`:`<h2 class="large-title">秒表</h2><div class="stopwatch" id="stopwatch-time">${stopwatchTime()}</div><div class="sheet-actions">${btn('stopwatch-reset','复位','secondary-button')}${btn('stopwatch-toggle',swRunning?'暂停':'开始','primary-button')}</div><p class="subtext" style="margin-top:25px;text-align:center">离开应用仍会计时，刷新页面后复位。</p>`}</div>`,{right:clockTab==='alarms'?btn('add-alarm',icon('plus'),'','aria-label="添加闹钟"'):''});}
function stopwatchTime(){const ms=swElapsed+(swRunning?Date.now()-swStart:0),sec=Math.floor(ms/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}.${Math.floor(ms%1000/100)}`;}
const notesBase=[{id:'next-time',title:'下次出门',text:'外套、相机，还有一件最重要的事。',fictional:true},{id:'shoot',title:'0520',text:'别再忘了，密码还是 0520 ❤️',fictional:true},{id:'photo-notes',title:'照片里的关键词',text:'街头、夜晚、雪山。\n\n打开相簿，还能再看一遍。',fictional:true}];
function notes(){const n=C.favoriteLeads(state,D),ready=n>=D.folderUnlockCount;return shell('备忘录',`<div class="padded"><h2 class="large-title">备忘录</h2><div class="list-group">${[...notesBase,...state.notes].map(n=>btn('memo',`<span class="row-label">${esc(n.title)}<small>备忘录</small></span>${icon('chevron')}`,'list-row',`data-id="${esc(n.id)}"`)).join('')}</div><div class="section-label">文件夹</div><div class="list-group">${btn('files',icon(ready?'folder':'lock')+`<span class="row-label">${ready?'.memories':'未命名的文件夹'}<small>${ready?'有些话，留在了这里':`收藏 ${D.folderUnlockCount} 个不同人物的章节后打开 · ${n}/${D.folderUnlockCount}`}</small></span>`+icon('chevron'),'list-row')}</div></div>`,{right:btn('add-note',icon('edit'),'','aria-label="新建备忘录"')});}
function memo(){const n=[...notesBase,...state.notes].find(x=>x.id===route.id)||notesBase[0];return shell('备忘录',`<div class="padded"><h2 style="font-size:24px;font-weight:550;line-height:1.5;margin:15px 0">${esc(n.title)}</h2><span class="memo-tag">备忘录</span>${n.id==='next-time'?`<div id="dali-note-content">${Y.note()}</div>`:`<div class="memo-content">${esc(n.text)}</div>`}</div>`,{right:!n.fictional?btn('delete-note',icon('trash'),'',`data-id="${esc(n.id)}" aria-label="删除这条备忘录"`):''});}
function files(){const count=C.favoriteLeads(state,D);if(count<D.folderUnlockCount)return shell('文件夹',`<div class="empty-state">${icon('lock')}<h3>还差一点，就能打开。</h3><p>收藏 ${D.folderUnlockCount} 个不同人物的章节。<br>目前已经收藏 ${count} 个。</p>${btn('app','去微信继续探索','secondary-button','data-app="wechat"')}</div>`);return shell('.memories',`<div class="padded"><p class="eyebrow">A LITTLE SOMETHING FOR YOU</p><div class="ending">${icon('folder')}<blockquote>真正留在手机里的，<br>不是联系人，<br>是记得的那句话。</blockquote><p>写给每一个记得的人</p></div><div class="sheet-actions">${btn('favorites','打开我的收藏','primary-button')}</div></div>`);}
function reminders(){return shell('提醒事项',`<div class="padded"><h2 class="large-title" style="color:#b99a4d">提醒事项</h2><div class="list-group">${state.reminders.map(r=>`<div class="reminder-row ${r.done?'done':''}"><button data-action="reminder-toggle" data-id="${esc(r.id)}" aria-label="${r.done?'取消完成':'完成'}${esc(r.text)}">${r.done?icon('check'):''}</button><span>${esc(r.text)}</span></div>`).join('')}</div>${btn('add-reminder',icon('plus')+'新提醒事项','secondary-button wide')}</div>`);}
function camera(){return Y.camera();}
function phoneApp(){return shell('电话',`<div class="padded"><p class="eyebrow" style="text-align:center;margin-top:15px">拨号键盘</p><div class="dial-display" id="dial-display">${esc(dial)}</div><div class="dial-pad">${['1','2','3','4','5','6','7','8','9','*','0','#'].map((n,i)=>btn('dial',n+`<small>${['','ABC','DEF','GHI','JKL','MNO','PQRS','TUV','WXYZ','','+',''][i]||'&nbsp;'}</small>`,'dial-key',`data-key="${n}"`)).join('')}</div>${btn('call',icon('phone'),'call-button','aria-label="呼叫"')}<div style="text-align:center">${btn('dial-delete','删除','subtext')}</div></div>`);}
function messages(){return shell('信息',`<div class="padded"><div class="sms-item">欢迎打开这部手机。去微信看看，那里有熟悉的名字。</div><div class="sms-item">你收藏的片段，会留在收藏夹里。</div>${state.sms.map(s=>`<div class="sms-item sent">${esc(s)}</div>`).join('')}</div>`,{footer:`<form class="sms-form" data-form="sms"><input id="sms-input" placeholder="信息" aria-label="信息" maxlength="300" required><button type="submit" aria-label="发送信息">${icon('arrow')}</button></form>`});}
function safari(){return X.safari();}
function weather(){return shell('天气',`<div class="weather-full"><p class="eyebrow" style="color:#ffffff99">天气</p><h2>海边</h2><div class="big-temp">28°</div><p>多云<br>最高 32° · 最低 24°</p><div class="weather-detail">傍晚多云，有风。适合留一点时间看日落。<div class="forecast">${['现在','18时','19时','20时','21时'].map((x,i)=>`<div><small>${x}</small>${icon(i>2?'moon':'cloud')}<b>${28-i}°</b></div>`).join('')}</div></div></div>`,{className:'weather-app'});}
function maps(){return Y.maps();}
function store(){return shell('App Store',`<div class="padded"><p class="eyebrow">ON THIS PHONE</p><h2 class="large-title">探索这部手机</h2><p class="subtext" style="margin-bottom:18px">这里的应用已经准备好了。点“打开”，从另一个入口继续探索。</p><div class="list-group">${apps.filter(a=>a[0]!=='store').map(([id,name])=>`<div class="list-row">${appIcon(id)}<span class="row-label">${name}</span>${btn('app','打开','pill green',`data-app="${id}"`)}</div>`).join('')}</div></div>`);}
function render(){X.beforeRender();applySettings();status();const views={lock,home,pin:passcode,wechat,room,photos:()=>photos(false),album:albumPage,favorites:()=>photos(true),settings,calendar,clock,notes,memo,files,reminders,camera,phone:phoneApp,messages,safari,calculator:()=>X.calculator(),moments:()=>X.moments(),weather,maps,store};screen.innerHTML=(views[route.app]||home)();if(route.app==='camera'){const el=$('.camera-layout');el.style.display='flex';el.style.flexDirection='column';}if(route.app==='messages'){$('.app-scroll').scrollTop=$('.app-scroll').scrollHeight;}X.afterRender();Y.afterRender(); }
function openApp(app){go(app);}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action,id=t.dataset.id;if(a==='shade-close'&&e.target!==t)return;if(X.action(a,t,e)||Y.action(a,t,e))return;
switch(a){
case 'app':case 'search-app':closeModal(true);openApp(t.dataset.app);break;
case 'back':back();break;
case 'pin':pin='';pinError=false;pendingApp=null;go('pin');break;
case 'unlock':unlock();break;
case 'lock-notification':pendingApp='wang';go('pin');break;
case 'lock-camera':pendingApp='camera';go('pin');break;
case 'lock-phone':state.unlocked=false;save();go('lock');break;
case 'pin-key':enterPin(t.dataset.key);break;
case 'flashlight':phone.classList.toggle('flashlight-on');toast(phone.classList.contains('flashlight-on')?'手电筒已开启':'手电筒已关闭');t.style.background=phone.classList.contains('flashlight-on')?'#fff9':'';break;
case 'room':case 'search-person':go('room',{id,scene:0});break;
case 'scene':go('room',{id:route.id,scene:Number(t.dataset.index)},true);break;
case 'memory':showModal('memory',{id});break;
case 'album':go('album',{id});break;
case 'photo':showModal('photo',{albumId:route.id,index:Number(t.dataset.index)});break;
case 'photo-step':movePhoto(Number(t.dataset.delta));break;

case 'favorite':{const before=C.favoriteLeads(state,D),added=C.collect(state,id);save();renderModal();const after=C.favoriteLeads(state,D);toast(added?'已收藏这个瞬间':'已取消收藏');if(before<D.folderUnlockCount&&after>=D.folderUnlockCount)setTimeout(()=>toast('隐藏档案已打开 · 去备忘录看看'),900);break;}
case 'modal-close':case 'shade-close':case 'modal-back':closeModal();break;
case 'intro':showModal('intro');break;
case 'search':showModal('search');break;
case 'second-page':showModal('second');break;
case 'person-info':showModal('person');break;
case 'favorites':go('favorites');break;
case 'wechat-tab':if(route.app!=='wechat')go('wechat');else $('#contact-search')?.focus();break;
case 'setting':{const k=t.dataset.key;if(k==='review'&&!state.settings.review){showModal('review');break;}state.settings[k]=!state.settings[k];save();render();break;}
case 'review-enable':closeModal();break;
case 'data-info':showModal('about-data');break;
case 'reset':showModal('reset');break;
case 'reset-confirm':state=C.defaults();save();dial='';pendingApp=null;go('lock',{},true);toast('已重新开始');break;
case 'month':calendarOffset+=Number(t.dataset.delta);render();break;
case 'date':calendarSelected=Number(t.dataset.date);render();break;
case 'today':calendarOffset=0;calendarSelected=new Date().getDate();render();break;
case 'clock-tab':clockTab=t.dataset.tab;render();break;
case 'alarm-toggle':state.alarms[Number(t.dataset.index)].on=!state.alarms[Number(t.dataset.index)].on;save();render();break;
case 'add-alarm':showModal('alarm');break;
case 'stopwatch-toggle':if(swRunning){swElapsed+=Date.now()-swStart;swRunning=false;}else{swStart=Date.now();swRunning=true;}render();break;
case 'stopwatch-reset':swElapsed=0;swStart=Date.now();render();break;
case 'add-note':showModal('note');break;
case 'memo':go('memo',{id});break;
case 'delete-note':state.notes=state.notes.filter(n=>n.id!==id);save();go('notes',{},true);toast('已删除这条备忘录');break;
case 'files':go('files');break;
case 'reminder-toggle':{const r=state.reminders.find(x=>x.id===id);if(r){r.done=!r.done;save();render();}break;}
case 'add-reminder':showModal('reminder');break;
case 'shutter':state.captures++;save();$('#camera-flash')?.classList.add('firing');setTimeout(()=>$('#camera-flash')?.classList.remove('firing'),320);setTimeout(()=>{if(route.app==='camera')showModal('capture');},250);break;
case 'capture-view':showModal('capture');break;
case 'capture-photos':go('photos');break;
case 'dial':if(dial.length<16)dial+=t.dataset.key;$('#dial-display').textContent=dial;break;
case 'dial-delete':dial=dial.slice(0,-1);$('#dial-display').textContent=dial;break;
case 'call':showModal('call');break;
}});
document.addEventListener('input',e=>{if(X.input(e.target)||Y.input(e.target))return;if(e.target.id==='contact-search'){const q=e.target.value.trim().toLowerCase();const list=D.people.filter(p=>(p.name+' '+(p.alias||'')).toLowerCase().includes(q));$('#contact-list').innerHTML=contactRows(list)||'<p class="no-results">没有找到这个联系人</p>';}if(e.target.id==='global-search')$('#search-results').innerHTML=searchResults(e.target.value);if(e.target.id==='brightness'){state.settings.brightness=Number(e.target.value);save();applySettings();}});
document.addEventListener('submit',e=>{const form=e.target.dataset.form;if(!form)return;e.preventDefault();if(form==='wx-message'){X.send();return;}if(form==='note'){const title=$('#note-title').value.trim(),text=$('#note-text').value.trim();if(!title||!text)return;state.notes.push({id:'n'+Date.now(),title,text,fictional:false});save();closeModal(true);render();toast('备忘录已保存');}if(form==='alarm'){state.alarms.push({time:$('#alarm-time').value,label:$('#alarm-label').value.trim()||'闹钟',on:true});state.alarms.sort((a,b)=>a.time.localeCompare(b.time));save();closeModal(true);render();}if(form==='reminder'){const text=$('#reminder-text').value.trim();if(!text)return;state.reminders.push({id:'r'+Date.now(),text,done:false});save();closeModal(true);render();}if(form==='sms'){const text=$('#sms-input').value.trim();if(!text)return;state.sms.push(text);save();render();toast('已保存');}});
document.addEventListener('keydown',e=>{if(modalStack.at(-1)?.kind==='photo'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();movePhoto(e.key==='ArrowLeft'?-1:1);return;}if(['Enter',' '].includes(e.key)&&e.target.matches?.('.dali-place-marker')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));return;}if(e.key==='Escape'){e.preventDefault();back();}if(route.app==='pin'&&!modalStack.length){if(/^\d$/.test(e.key)){const k=document.querySelector(`[data-action="pin-key"][data-key="${e.key}"]`);k?.click();}if(e.key==='Backspace'){e.preventDefault();enterPin('⌫');}if(e.key==='Enter'){e.preventDefault();if(pin.length===4)enterPin('Enter');} }if(e.key==='Tab'&&modalStack.length){const els=[...modalRoot.querySelectorAll('button,a[href],input,textarea,[tabindex="0"]')].filter(x=>!x.disabled);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('#home-indicator').addEventListener('click',()=>{if(route.app==='lock'){go('pin');}else if(route.app==='pin'){go('lock',{},true);}else{go('home');}});
let pointerStart=null;
phone.addEventListener('pointerdown',e=>{pointerStart={x:e.clientX,y:e.clientY};});
phone.addEventListener('pointerup',e=>{if(!pointerStart)return;const dy=pointerStart.y-e.clientY,dx=e.clientX-pointerStart.x;pointerStart=null;if(modalStack.at(-1)?.kind==='photo'&&Math.abs(dx)>45&&Math.abs(dy)<80){movePhoto(dx>0?-1:1);return;}if(dy>60&&Math.abs(dx)<70&&route.app==='lock'&&!modalStack.length){pin='';pinError=false;go('pin');}});
document.addEventListener('error',e=>{if(e.target.matches?.('.viewer-image')){e.target.style.visibility='hidden';$('.viewer-error').hidden=false;}},true);
setInterval(()=>{const value=time();document.querySelectorAll('[data-clock]').forEach(el=>{if(el.textContent!==value)el.textContent=value;});},1000);
setInterval(()=>{const sw=$('#stopwatch-time');if(sw&&swRunning)sw.textContent=stopwatchTime();},100);
render();
})();
